// ---------- OpenAPI ----------
type OpRow = { spec: string; method: string; path: string; id: string; summary: string; status: string; scopes: string };
export function collectOperations(): OpRow[] {
  const rows: OpRow[] = [];
  for (const spec of ["docs/api/cyrus-v1.openapi.yaml", "docs/api/nxeon-platform-v1.openapi.yaml"]) {
    if (!exists(spec)) continue;
    const lines = rd(spec).split("\n");
    let inPaths = false;
    let cur: OpRow | null = null;
    let curPath = "";
    for (const l of lines) {
      if (/^paths:/.test(l)) { inPaths = true; continue; }
      if (inPaths && /^[a-z]/.test(l) && !/^paths:/.test(l)) inPaths = false;
      if (!inPaths) continue;
      const p = /^ {2}["']?(\/[^"':]*)["']?:/.exec(l);
      if (p) { curPath = p[1]; continue; }
      const m = /^ {4}(get|post|put|patch|delete):/.exec(l);
      if (m) { cur = { spec: path.basename(spec).replace(".openapi.yaml", ""), method: m[1].toUpperCase(), path: curPath, id: "", summary: "", status: "", scopes: "" }; rows.push(cur); continue; }
      if (!cur) continue;
      let v: RegExpExecArray | null;
      if ((v = /^ {6}operationId:\s*["']?([^"']+)["']?/.exec(l))) cur.id = v[1];
      else if ((v = /^ {6}summary:\s*["']?(.*?)["']?\s*$/.exec(l))) cur.summary = v[1];
      else if ((v = /^ {6}x-[a-z]+-status:\s*["']?([^"']+)["']?/.exec(l))) cur.status = v[1];
      else if ((v = /^ {6}x-[a-z]+-scopes:\s*(.*)$/.exec(l))) cur.scopes = v[1].replace(/[\[\]"']/g, "").trim();
    }
  }
  return rows;
}

function openapiPage(): string {
  const rows = collectOperations();
  const by = (s: string) => rows.filter((r) => r.spec === s);
  const tbl = (rs: OpRow[]) => ["| Method | Path | operationId | Status | Scopes | Summary |", "|---|---|---|---|---|---|", ...rs.map((r) => `| ${r.method} | ${code(r.path)} | ${code(r.id)} | ${cell(r.status)} | ${cell(r.scopes)} | ${cell(r.summary)} |`), ""].join("\n");
  return [
    gen("OpenAPI operations", "Parsed from docs/api/cyrus-v1.openapi.yaml and docs/api/nxeon-platform-v1.openapi.yaml (themselves generated from the Zod schemas by tools/cyrus-api/gen-openapi.ts)."),
    "Status `live` = answered by code behind the API flag; `planned` = documented contract only. Both APIs are OFF until the owner enables them.",
    "",
    `## Cyrus API v1 (${by("cyrus-v1").length} operations)`, "", tbl(by("cyrus-v1")),
    `## Nxeon Platform API v1 (${by("nxeon-platform-v1").length} operations)`, "", tbl(by("nxeon-platform-v1")),
  ].join("\n");
}

