#!/usr/bin/env tsx
// Cyrus docs generator (r46). Builds the REFERENCE pages of docs/cyrus/ straight from the code, with zero model tokens:
// flags/settings/env, routes, DB tables, version registry, adapters + capability matrix, OpenAPI operations,
// feature -> flag -> doc map, module map, scripts and test inventory.
//
//   npx tsx scripts/cyrus/docs-build.ts            write docs/cyrus/reference/*.md
//   npx tsx scripts/cyrus/docs-build.ts --check    exit 1 when a committed page is stale (what test/cyrus-docs-coverage.test.ts does)
//
// Rules: deterministic (no dates, no absolute paths, sorted), read-only on the code, never prints a secret value (it only
// records NAMES of env vars/settings and, for defaults, the literal fallback written next to the name in code).
// The hand-written narrative pages (00..14) are NOT touched; see docs/cyrus/14-how-to-work-here.md "docs update checklist".
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { ADAPTERS } from "../../lib/cyrus/adapters";
import { CYRUS_GAMES } from "../../lib/cyrus/games";
import { cyrusTables } from "./data-split/tables.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const ROOT = path.resolve(HERE, "..", "..");
export const REF_DIR = "docs/cyrus/reference";

const SCAN_ROOTS = ["lib", "app", "components", "services", "worker", "scripts", "deploy", "platform", "apps", "middleware.ts", "next.config.ts", "instrumentation.ts", "tools"];
const SKIP_DIRS = new Set(["node_modules", ".next", ".git", "dist", "build", "test", "__snapshots__", ".cyrus-local", "fixtures"]);
const CODE_EXT = /\.(ts|tsx|js|mjs|cjs|sh|service|yml|yaml)$/;

const rd = (rel: string) => readFileSync(path.join(ROOT, rel), "utf8");
const exists = (rel: string) => existsSync(path.join(ROOT, rel));
const cell = (s: unknown) => String(s ?? "").replace(/\|/g, "¦").replace(/\r?\n/g, " ").trim();
const code = (s: string) => (s ? "`" + s.replace(/`/g, "'") + "`" : "");

function walk(rel: string, out: string[] = []): string[] {
  const abs = path.join(ROOT, rel);
  if (!existsSync(abs)) return out;
  const st = statSync(abs);
  if (st.isFile()) {
    if (CODE_EXT.test(rel) && !/\.test\.(ts|tsx)$/.test(rel) && !/\.d\.ts$/.test(rel)) out.push(rel);
    return out;
  }
  for (const n of readdirSync(abs).sort()) {
    if (SKIP_DIRS.has(n) || n.startsWith(".")) continue;
    walk(rel + "/" + n, out);
  }
  return out;
}

let FILES_CACHE: string[] | null = null;
function allFiles(): string[] {
  if (!FILES_CACHE) FILES_CACHE = SCAN_ROOTS.flatMap((r) => walk(r)).sort();
  return FILES_CACHE;
}

const cyrusRelevant = (rel: string, text: string) =>
  /cyrus|mod-builder|modbuilder|nxeon-platform/i.test(rel) || /lib\/cyrus|CYRUS_|Cyrus|cyrus_/.test(text);

// ---------- flags / settings / env ----------
export type NameKind = "env" | "setting";
export type NameRow = { name: string; kind: NameKind; files: string[]; defaultHint: string; doc: string };

const ENV_TOKEN = /\b(CYRUS_[A-Z0-9_]+|MB_[A-Z0-9_]+)\b/g;
const SETTING_TOKEN = /["'](cyrus_[a-z0-9_]+)["']/g;

/** A CYRUS_/MB_ token counts as an env var/flag only where it is used as a string/env reference, not as a TS identifier. */
function envUses(text: string, rel: string): Set<string> {
  const found = new Set<string>();
  const shell = /\.(sh|service|yml|yaml)$/.test(rel) || /Dockerfile/.test(rel);
  for (const m of text.matchAll(/process\.env\.([A-Z][A-Z0-9_]*)|process\.env\[\s*["']([A-Z][A-Z0-9_]*)["']\s*\]|["']((?:CYRUS|MB)_[A-Z0-9_]+)["']|`((?:CYRUS|MB)_[A-Z0-9_]+)`|\benv\.((?:CYRUS|MB)_[A-Z0-9_]+)\b/g)) {
    const n = m[1] ?? m[2] ?? m[3] ?? m[4] ?? m[5];
    if (n && (/^(CYRUS|MB)_/.test(n))) found.add(n);
  }
  if (shell) for (const m of text.matchAll(ENV_TOKEN)) found.add(m[1]);
  // names written inside prose comments of a file that also configures them are caught by the quoted forms above
  return found;
}

function otherEnv(text: string): Set<string> {
  const found = new Set<string>();
  for (const m of text.matchAll(/process\.env\.([A-Z][A-Z0-9_]*)|process\.env\[\s*["']([A-Z][A-Z0-9_]*)["']\s*\]/g)) {
    const n = m[1] ?? m[2];
    if (n && !/^(CYRUS|MB)_/.test(n)) found.add(n);
  }
  return found;
}

function firstLineOf(text: string, token: string): { line: number; lines: string[] } | null {
  const lines = text.split("\n");
  const i = lines.findIndex((l) => l.includes(token));
  return i < 0 ? null : { line: i, lines };
}

function defaultHintFor(name: string, text: string): string {
  const esc = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pats = [
    new RegExp(`process\\.env\\.${esc}\\s*(?:\\?\\?|\\|\\|)\\s*([^;,)\\n]{1,40})`),
    new RegExp(`process\\.env\\[\\s*["']${esc}["']\\s*\\]\\s*(?:\\?\\?|\\|\\|)\\s*([^;,)\\n]{1,40})`),
    new RegExp(`(?:env\\w*|int\\w*|bool\\w*|num\\w*|getSetting\\w*|setting\\w*)\\(\\s*["']${esc}["']\\s*,\\s*([^)\\n]{1,40})\\)`),
    new RegExp(`\\$\\{${esc}:-([^}]{0,40})\\}`),
    new RegExp(`${esc}=([A-Za-z0-9_./:-]{1,40})`),
  ];
  for (const p of pats) {
    const m = p.exec(text);
    if (m) return m[1].trim().replace(/\s+$/, "");
  }
  return "";
}

function docHintFor(token: string, text: string): string {
  const hit = firstLineOf(text, token);
  if (!hit) return "";
  const { line, lines } = hit;
  const trailing = /\/\/\s*(.+)$/.exec(lines[line]);
  if (trailing && !trailing[1].includes(token)) return trailing[1].trim().slice(0, 150);
  // nearest comment lines directly above (up to 3), else the file's header comment
  const above: string[] = [];
  for (let j = line - 1; j >= 0 && above.length < 3; j--) {
    const t = lines[j].trim();
    if (/^(\/\/|\*|\/\*\*?)/.test(t)) above.unshift(t.replace(/^(\/\/+|\/\*+|\*+\/?|\*)\s?/, "").replace(/\*\/$/, "").trim());
    else break;
  }
  const joined = above.join(" ").trim();
  if (joined) return joined.slice(0, 150);
  const head = lines.slice(0, 6).filter((l) => /^\s*\/\//.test(l)).map((l) => l.replace(/^\s*\/\/+\s?/, "")).join(" ").trim();
  return head.slice(0, 150);
}

export function collectNames(): { names: NameRow[]; other: { name: string; files: string[] }[] } {
  const envMap = new Map<string, { files: Set<string>; first?: { text: string; token: string } }>();
  const setMap = new Map<string, { files: Set<string>; first?: { text: string; token: string } }>();
  const otherMap = new Map<string, Set<string>>();
  for (const rel of allFiles()) {
    const text = rd(rel);
    const relevant = cyrusRelevant(rel, text);
    if (!relevant) continue;
    for (const n of envUses(text, rel)) {
      if (n.startsWith("MB_") && !/modbuilder|mod-builder|cyrus|deploy\/|scripts\//.test(rel)) continue;
      const e = envMap.get(n) ?? { files: new Set<string>() };
      e.files.add(rel);
      e.first ??= { text, token: n };
      envMap.set(n, e);
    }
    for (const m of text.matchAll(SETTING_TOKEN)) {
      const n = m[1];
      const e = setMap.get(n) ?? { files: new Set<string>() };
      e.files.add(rel);
      e.first ??= { text, token: n };
      setMap.set(n, e);
    }
    if (/lib\/cyrus|lib\/cyrus-|lib\/nxeon-platform|services\/modbuilder|scripts\/cyrus|\/cyrus/.test(rel)) {
      for (const n of otherEnv(text)) {
        const s = otherMap.get(n) ?? new Set<string>();
        s.add(rel);
        otherMap.set(n, s);
      }
    }
  }
  const mk = (map: typeof envMap, kind: NameKind): NameRow[] =>
    [...map].map(([name, v]) => {
      // pick the file with the most informative default as hint source
      let hint = "";
      let doc = "";
      for (const f of [...v.files].sort()) {
        const t = rd(f);
        hint = hint || defaultHintFor(name, t);
        doc = doc || docHintFor(name, t);
        if (hint && doc) break;
      }
      return { name, kind, files: [...v.files].sort(), defaultHint: hint, doc };
    });
  const names = [...mk(envMap, "env"), ...mk(setMap, "setting")].sort((a, b) => a.name.localeCompare(b.name));
  const other = [...otherMap].map(([name, s]) => ({ name, files: [...s].sort() })).sort((a, b) => a.name.localeCompare(b.name));
  return { names, other };
}

function areaOf(file: string): string {
  const m = /^lib\/cyrus\/([a-z0-9-]+)\//.exec(file);
  if (m) return m[1];
  if (/^services\/modbuilder/.test(file)) return "build service";
  if (/^app\//.test(file)) return "app";
  if (/^scripts\//.test(file)) return "scripts";
  if (/^lib\/cyrus-/.test(file) || /^lib\/nxeon-platform/.test(file)) return file.split("/")[1];
  if (/^lib\/actions-cyrus/.test(file)) return "admin actions";
  if (/^worker\//.test(file)) return "worker";
  return file.split("/")[0];
}

function flagsPage(): string {
  const { names, other } = collectNames();
  const env = names.filter((n) => n.kind === "env");
  const settings = names.filter((n) => n.kind === "setting");
  const feat = loadFeatures();
  const featOf = new Map<string, string[]>();
  for (const f of feat) for (const fl of f.flags) featOf.set(fl, [...(featOf.get(fl) ?? []), f.title]);
  const row = (n: NameRow) => {
    const areas = [...new Set(n.files.map(areaOf))].sort().slice(0, 4).join(", ");
    const shown = n.files.slice(0, 2).map(code).join(" ") + (n.files.length > 2 ? ` +${n.files.length - 2}` : "");
    return `| ${code(n.name)} | ${cell(n.defaultHint ? code(n.defaultHint) : "")} | ${cell(areas)} | ${cell(shown)} | ${cell((featOf.get(n.name) ?? []).join("; "))} | ${cell(n.doc)} |`;
  };
  const head = "| Name | Default / fallback written in code | Area | Read in | Feature (map) | Nearest comment |\n|---|---|---|---|---|---|";
  return [
    gen("Flags, settings and environment variables", "scripts/cyrus/docs-build.ts scans lib, app, services, worker, scripts, deploy, platform and apps for Cyrus names (no values are ever read or printed)."),
    `Counts: ${env.length} environment flags/variables (CYRUS_*, MB_*), ${settings.length} Settings keys (cyrus_*), ${other.length} other environment variables read by Cyrus code.`,
    "",
    "How to read this: **env flags** (CYRUS_*) are read from the process environment of the web app, worker or build service. **Settings** (cyrus_*) live in the Nxeon `Setting` table and are changed from the admin (Flags tab) or SQL; they are read through `host.settings`. A blank default means the code reads the name but has no literal fallback next to it (usually `=== \"1\"` style: off unless set). Everything is OFF/inert unless this table or [the deploy runbook](../../CYRUS-DEPLOY-RUNBOOK.md) says otherwise. Secret values are never written here: see [07 operations](../07-operations.md) for where secrets live.",
    "",
    "## Environment flags and variables (CYRUS_*, MB_*)",
    "",
    head,
    ...env.map(row),
    "",
    "## Settings keys (cyrus_*)",
    "",
    head,
    ...settings.map(row),
    "",
    "## Other environment variables read by Cyrus code",
    "",
    "| Variable | Read in |",
    "|---|---|",
    ...other.map((o) => `| ${code(o.name)} | ${cell(o.files.slice(0, 3).map(code).join(" ") + (o.files.length > 3 ? ` +${o.files.length - 3}` : ""))} |`),
    "",
  ].join("\n");
}

// ---------- routes ----------
export type RouteRow = { url: string; file: string; methods: string[]; flags: string[]; kind: "api" | "page" };

function urlOf(rel: string): string {
  const seg = rel.replace(/^app\//, "").replace(/\/(route|page)\.tsx?$/, "").split("/").filter((s) => !/^\(.*\)$/.test(s) && !s.startsWith("@"));
  return "/" + seg.join("/");
}

export function collectRoutes(): RouteRow[] {
  const rows: RouteRow[] = [];
  for (const rel of allFiles()) {
    if (!/^app\/.*\/(route|page)\.tsx?$/.test(rel) && !/^app\/(route|page)\.tsx?$/.test(rel)) continue;
    const text = rd(rel);
    if (!cyrusRelevant(rel, text)) continue;
    const kind = /\/route\.tsx?$/.test(rel) ? "api" : "page";
    const methods = kind === "api"
      ? ["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"].filter((m) => new RegExp(`export\\s+(?:async\\s+)?(?:function|const)\\s+${m}\\b`).test(text) || new RegExp(`export\\s*\\{[^}]*\\b${m}\\b`).test(text))
      : [];
    const flags = [...new Set([...envUses(text, rel), ...[...text.matchAll(SETTING_TOKEN)].map((m) => m[1])])].sort();
    rows.push({ url: urlOf(rel), file: rel, methods, flags, kind });
  }
  return rows.sort((a, b) => a.url.localeCompare(b.url) || a.file.localeCompare(b.file));
}

function routesPage(): string {
  const rows = collectRoutes();
  const api = rows.filter((r) => r.kind === "api");
  const pages = rows.filter((r) => r.kind === "page");
  const line = (r: RouteRow) => `| ${code(r.url)} | ${cell(r.methods.join(" "))} | ${cell(r.flags.map(code).join(" "))} | ${code(r.file)} |`;
  return [
    gen("Routes", "Every app/**/route.ts and app/**/page.tsx that is Cyrus related (path contains cyrus / mod-builder, or the file mentions Cyrus)."),
    `${api.length} API routes, ${pages.length} pages. "Flags referenced" lists the CYRUS_*/MB_*/cyrus_* names that appear IN THAT FILE; a gate can also come from a helper it calls (see the feature map and the page's docs).`,
    "",
    "## API routes",
    "",
    "| URL | Methods | Flags referenced | File |",
    "|---|---|---|---|",
    ...api.map(line),
    "",
    "## Pages",
    "",
    "| URL | | Flags referenced | File |",
    "|---|---|---|---|",
    ...pages.map(line),
    "",
  ].join("\n");
}

// ---------- DB tables ----------
export type TableRow = { name: string; source: string; owner: string; schemaLine: number | null; migrations: string[] };

export function collectTables(): TableRow[] {
  const schema = rd("prisma/schema.prisma");
  const schemaLines = schema.split("\n");
  const modelLine = (name: string) => {
    const i = schemaLines.findIndex((l) => new RegExp(`^model ${name} \\{`).test(l));
    return i < 0 ? null : i + 1;
  };
  const sqlFiles = [
    ...readdirSync(path.join(ROOT, "prisma")).filter((f) => f.endsWith(".sql")).map((f) => "prisma/" + f),
    ...readdirSync(path.join(ROOT, "prisma/manual-migrations")).filter((f) => f.endsWith(".sql")).map((f) => "prisma/manual-migrations/" + f),
  ].sort();
  const migOf = new Map<string, string[]>();
  for (const f of sqlFiles) {
    for (const m of rd(f).matchAll(/CREATE TABLE (?:IF NOT EXISTS )?"?([A-Za-z][A-Za-z0-9_]*)"?/g)) {
      migOf.set(m[1], [...new Set([...(migOf.get(m[1]) ?? []), f])]);
    }
  }
  const owned = new Map(cyrusTables(ROOT).map((t: { name: string; source: string }) => [t.name, t.source]));
  const names = new Set<string>(owned.keys());
  for (const m of schema.matchAll(/^model (Cyrus[A-Za-z]*) \{/gm)) names.add(m[1]);
  for (const k of migOf.keys()) if (/^Cyrus/.test(k)) names.add(k);
  names.add("ModBuild");
  const rows: TableRow[] = [];
  for (const name of [...names].sort()) {
    const inSchema = modelLine(name) !== null;
    const inSql = migOf.has(name);
    const source = inSchema && inSql ? "prisma + manual SQL" : inSchema ? "prisma" : "manual SQL only";
    const owner = name === "ModBuild" ? "Nxeon DB today (the build engine seam); follows the build engine on move day"
      : owned.has(name) ? "Cyrus (moves to the Cyrus database at the data split)"
      : /^Cyrus/.test(name) ? "Nxeon side of the bridge (stays in Nxeon)" : "Nxeon";
    rows.push({ name, source, owner, schemaLine: modelLine(name), migrations: migOf.get(name) ?? [] });
  }
  return rows;
}

function tablesPage(): string {
  const rows = collectTables();
  const sql = readdirSync(path.join(ROOT, "prisma/manual-migrations")).filter((f) => /cyrus/.test(f)).sort();
  return [
    gen("Database tables", "Cyrus tables are derived from the CyrusDb type (lib/cyrus/host/types.ts), prisma/schema.prisma models named Cyrus*, and CREATE TABLE statements in prisma/*.sql + prisma/manual-migrations/*.sql."),
    `${rows.length} tables. Owner column: **Cyrus** tables are what \`scripts/cyrus/data-split/\` moves to a separate Cyrus Postgres; Cyrus code reaches them only through \`cyrusDb\` (lib/cyrus/db.ts). Whether a manual migration is APPLIED in production is not knowable from the repo: see [the deploy runbook](../../CYRUS-DEPLOY-RUNBOOK.md) and [07 operations](../07-operations.md). No migration has been applied to production by the Cyrus programme without owner approval.`,
    "",
    "| Table | Defined as | schema.prisma line | Created by (SQL file) | Owner |",
    "|---|---|---|---|---|",
    ...rows.map((r) => `| ${code(r.name)} | ${cell(r.source)} | ${r.schemaLine ?? ""} | ${cell(r.migrations.map(code).join(" "))} | ${cell(r.owner)} |`),
    "",
    "## Cyrus manual migration files",
    "",
    ...sql.map((f) => `- ${code("prisma/manual-migrations/" + f)}`),
    ...readdirSync(path.join(ROOT, "prisma")).filter((f) => f.endsWith(".sql") && /cyrus/.test(f)).sort().map((f) => `- ${code("prisma/" + f)}`),
    "",
  ].join("\n");
}

// ---------- version registry ----------
type RegVersion = { id: string; family: string; javaRelease: number; status: string; buildable: boolean; paperCoordinate: string | null; resourcePack: { major: number; minor: number } | null; dataPack: { major: number; minor: number } | null; resourcePackClientVerified: boolean; capabilities: string[]; paperBuild?: number | null; paperServerSha256?: string | null };

function versionsPage(): string {
  const reg = JSON.parse(rd("lib/cyrus/versions/registry.json")) as { updated: string; notes: string[]; versions: RegVersion[] };
  const pf = (p: { major: number; minor: number } | null) => (p ? `${p.major}.${p.minor}` : "not verified");
  return [
    gen("Minecraft version registry", "Rendered from lib/cyrus/versions/registry.json (the single source for pack formats, Java release, Paper pins and capabilities)."),
    `Registry last updated ${reg.updated}. ${reg.versions.length} versions. A pack number of \`not verified\` means consumers fail closed. \`Client-verified\` is false everywhere: no resource pack from this registry has been loaded by a real Minecraft client yet (see [09 testing](../09-testing-and-verification.md)). A version without a Paper server pin cannot be test-flown.`,
    "",
    "| Version | Family | Status | Buildable | Java | Paper API coordinate | Paper server build | Resource pack | Data pack | Client-verified | Capabilities |",
    "|---|---|---|---|---|---|---|---|---|---|---|",
    ...reg.versions.map((v) => `| ${code(v.id)} | ${v.family} | ${v.status} | ${v.buildable ? "yes" : "no"} | ${v.javaRelease} | ${cell(v.paperCoordinate ? code(v.paperCoordinate) : "none")} | ${v.paperBuild ?? "none"} | ${pf(v.resourcePack)} | ${pf(v.dataPack)} | ${v.resourcePackClientVerified ? "yes" : "no"} | ${cell(v.capabilities.join(", "))} |`),
    "",
    "## Registry notes (verbatim)",
    "",
    ...reg.notes.map((n) => `- ${cell(n)}`),
    "",
  ].join("\n");
}

// ---------- adapters ----------
async function adaptersPage(): Promise<string> {
  const out: string[] = [
    gen("Game adapters and capability matrix", "Rendered from lib/cyrus/adapters (ADAPTERS), lib/cyrus/games.ts (CYRUS_GAMES) and lib/cyrus/games/*.ts (per-game support packs)."),
    "Maturity words are literal: planned = nothing built; template = canned preview code only; beta = real AI build + compile + scan; stable = beta plus boot and functional tests on every build. **Only Minecraft has an adapter today.** Every other game is on hold by owner decision (2026-10-11); Terraria, Valheim and Zomboid have verified knowledge packs only.",
    "",
    "## Game registry (what the UI shows)",
    "",
    "| Game | id | Status | Loader | Builds | Versions |",
    "|---|---|---|---|---|---|",
    ...CYRUS_GAMES.map((g) => `| ${cell(g.name)} | ${code(g.id)} | ${g.status} | ${cell(g.loader)} | ${cell(g.builds)} | ${cell(g.versions.length ? g.versions.join(", ") : "none")} |`),
    "",
    "## Adapters",
    "",
    `${ADAPTERS.length} adapter(s): ${ADAPTERS.map((a) => code(a.game)).join(", ")}.`,
    "",
  ];
  for (const a of ADAPTERS) {
    const vers = a.versions.list();
    out.push(`### ${a.name} (${code(a.game)}) - maturity: ${a.maturity}`, "");
    out.push(`- Default route: ${code(a.defaultRoute)}; toolchain: ${cell(a.toolchain.language)} / ${cell(a.toolchain.compiler)}; scanner ${code(a.toolchain.scanner)}.`);
    out.push(`- Install: side ${a.install.side}, path ${code(a.install.serverPath)}, restart needed: ${a.install.needsRestart ? "yes" : "no"}, hot reload: ${a.install.hotReload ? "yes" : "no"}. ${cell(a.install.summary)}`);
    out.push(`- Test lane: compile ${a.testLane.compile}, scan ${a.testLane.scan}, boot ${a.testLane.boot}, functional ${a.testLane.functional}. ${cell(a.testLane.notes)}`);
    out.push(`- Knowledge: ${a.knowledge.kind} (${code(a.knowledge.ref)}). Route rules: ${a.routeRules.length}. Asset profile: ${a.assetProfile ? "yes" : "no"}.`, "");
    out.push("Artifact types:", "", "| Route | Availability | Packaging | Side | Note |", "|---|---|---|---|---|");
    for (const t of a.artifacts) out.push(`| ${code(t.route)} | ${t.availability} | ${cell(t.packaging)} | ${t.side} | ${cell(t.note)} |`);
    out.push("", "Asset delivery by asset kind:", "", "| Asset kind | Supported | Via | Availability | Note |", "|---|---|---|---|---|");
    for (const k of Object.keys(a.assetDelivery).sort()) {
      const d = (a.assetDelivery as Record<string, { supported: boolean; via: string; availability: string; note: string }>)[k];
      out.push(`| ${code(k)} | ${d.supported ? "yes" : "no"} | ${d.via} | ${d.availability} | ${cell(d.note)} |`);
    }
    out.push("", "Versions known to the adapter:", "", "| Version | Status | Buildable | Capabilities |", "|---|---|---|---|");
    for (const v of vers) out.push(`| ${code(v.id)} | ${v.status} | ${v.buildable ? "yes" : "no"} | ${cell(v.capabilities.join(", "))} |`);
    out.push("", "Router rules (id: what triggers it):", "");
    for (const r of a.routeRules) out.push(`- ${code(r.id)}${r.route ? " -> " + code(r.route) : ""}${r.requiresCapability ? `; needs capability ${code(r.requiresCapability.capability)}` : ""}${r.assetKinds?.length ? `; asset kinds ${r.assetKinds.join(", ")}` : ""}`);
    out.push("");
  }
  // per-game support packs
  out.push("## Per-game support packs (lib/cyrus/games/*.ts)", "", "| Game | Language | Loader | Versions covered | Install side | Knowledge sources / unknowns |", "|---|---|---|---|---|---|");
  for (const f of readdirSync(path.join(ROOT, "lib/cyrus/games")).filter((n) => /^[a-z]+\.ts$/.test(n) && !/\.(validate|knowledge)\./.test(n) && n !== "support.ts").sort()) {
    const text = rd("lib/cyrus/games/" + f);
    const g = (re: RegExp) => re.exec(text)?.[1] ?? "";
    const id = f.replace(/\.ts$/, "");
    const vers = [...text.matchAll(/version:\s*"([^"]+)"/g)].map((m) => m[1]).slice(0, 6).join(", ");
    out.push(`| ${code(id)} | ${cell(g(/language:\s*"([^"]+)"/))} | ${cell(g(/loader:\s*\{\s*name:\s*"([^"]+)"/))} | ${cell(vers)} | ${cell(g(/side:\s*"([^"]+)"/))} | ${/unknowns/.test(text) ? "has an `unknowns` list" : "see file"} |`);
  }
  out.push("");
  return out.join("\n");
}

// ---------- OpenAPI ----------
type OpRow = { spec: string; method: string; path: string; id: string; summary: string; status: string; scopes: string };
export function collectOperations(): OpRow[] {
  const rows: OpRow[] = [];
  for (const spec of ["docs/api/cyrus-v1.openapi.yaml", "docs/api/nxeon-platform-v1.openapi.yaml"]) {
    if (!exists(spec)) continue;
    const lines = rd(spec).split("\n");
    let inPaths = false;
    let cur: OpRow | null = null;
    let curPath = "";
    for (const l of lines) {
      if (/^paths:/.test(l)) { inPaths = true; continue; }
      if (inPaths && /^[a-z]/.test(l) && !/^paths:/.test(l)) inPaths = false;
      if (!inPaths) continue;
      const p = /^ {2}["']?(\/[^"':]*)["']?:/.exec(l);
      if (p) { curPath = p[1]; continue; }
      const m = /^ {4}(get|post|put|patch|delete):/.exec(l);
      if (m) { cur = { spec: path.basename(spec).replace(".openapi.yaml", ""), method: m[1].toUpperCase(), path: curPath, id: "", summary: "", status: "", scopes: "" }; rows.push(cur); continue; }
      if (!cur) continue;
      let v: RegExpExecArray | null;
      if ((v = /^ {6}operationId:\s*["']?([^"']+)["']?/.exec(l))) cur.id = v[1];
      else if ((v = /^ {6}summary:\s*["']?(.*?)["']?\s*$/.exec(l))) cur.summary = v[1];
      else if ((v = /^ {6}x-[a-z]+-status:\s*["']?([^"']+)["']?/.exec(l))) cur.status = v[1];
      else if ((v = /^ {6}x-[a-z]+-scopes:\s*(.*)$/.exec(l))) cur.scopes = v[1].replace(/[\[\]"']/g, "").trim();
    }
  }
  return rows;
}

function openapiPage(): string {
  const rows = collectOperations();
  const by = (s: string) => rows.filter((r) => r.spec === s);
  const tbl = (rs: OpRow[]) => ["| Method | Path | operationId | Status | Scopes | Summary |", "|---|---|---|---|---|---|", ...rs.map((r) => `| ${r.method} | ${code(r.path)} | ${code(r.id)} | ${cell(r.status)} | ${cell(r.scopes)} | ${cell(r.summary)} |`), ""].join("\n");
  return [
    gen("OpenAPI operations", "Parsed from docs/api/cyrus-v1.openapi.yaml and docs/api/nxeon-platform-v1.openapi.yaml (themselves generated from the Zod schemas by tools/cyrus-api/gen-openapi.ts)."),
    "Status `live` = answered by code behind the API flag; `planned` = documented contract only. Both APIs are OFF until the owner enables them.",
    "",
    `## Cyrus API v1 (${by("cyrus-v1").length} operations)`, "", tbl(by("cyrus-v1")),
    `## Nxeon Platform API v1 (${by("nxeon-platform-v1").length} operations)`, "", tbl(by("nxeon-platform-v1")),
  ].join("\n");
}

// ---------- feature map ----------
export type Feature = { title: string; area: string; flags: string[]; doc: string; branch?: string; state: string };
export function loadFeatures(): Feature[] {
  const f = "docs/cyrus/_data/features.json";
  return exists(f) ? (JSON.parse(rd(f)).features as Feature[]) : [];
}

function featurePage(): string {
  const feats = loadFeatures();
  return [
    gen("Feature to flag to doc map", "Curated source: docs/cyrus/_data/features.json (the only hand-maintained input of the reference set). test/cyrus-docs-coverage.test.ts fails when a flag named there no longer exists in code or a doc path is wrong."),
    `${feats.length} features. State words: **live** (in production), **built** (merged to the integration branch, verified on node-2, not deployed), **partial**, **pending** (branch not merged), **parked** (owner hold).`,
    "",
    "| Feature | Area | State | Flags / settings | Branch | Doc |",
    "|---|---|---|---|---|---|",
    ...feats.map((f) => `| ${cell(f.title)} | ${cell(f.area)} | ${cell(f.state)} | ${cell(f.flags.map(code).join(" ") || "none (always on / inert)")} | ${cell(f.branch ? code(f.branch) : "")} | [${cell(f.doc)}](../${f.doc.replace(/^docs\/cyrus\//, "")}) |`),
    "",
  ].join("\n");
}

// ---------- module map ----------
function headComment(rel: string): string {
  const t = rd(rel).split("\n").slice(0, 14);
  const parts: string[] = [];
  for (const l of t) {
    const m = /^\s*(?:\/\/+|\/\*\*?|\*)\s?(.*?)\s*(?:\*\/)?$/.exec(l);
    if (m && m[1] && !/^(eslint|@ts-|use client|use server)/.test(m[1])) parts.push(m[1]);
    else if (parts.length) break;
    if (parts.join(" ").length > 170) break;
  }
  return parts.join(" ").slice(0, 190);
}

function modulesPage(): string {
  const rows: string[] = [];
  const dirs = ["lib/cyrus", "lib/cyrus-client", "lib/cyrus-bridge", "lib/cyrus-mods", "lib/nxeon-platform", "services/modbuilder", "components/cyrus", "worker"];
  for (const d of dirs) {
    if (!exists(d)) continue;
    const entries = readdirSync(path.join(ROOT, d)).sort();
    const subdirs = entries.filter((n) => statSync(path.join(ROOT, d, n)).isDirectory() && !SKIP_DIRS.has(n) && !n.startsWith("."));
    const topFiles = entries.filter((n) => /\.(ts|tsx|js)$/.test(n) && !/\.d\.ts$/.test(n));
    const count = (rel: string): number => {
      let c = 0;
      for (const n of readdirSync(path.join(ROOT, rel))) {
        const p = rel + "/" + n;
        const st = statSync(path.join(ROOT, p));
        if (st.isDirectory()) { if (!SKIP_DIRS.has(n) && !n.startsWith(".")) c += count(p); } else if (/\.(ts|tsx|js)$/.test(n)) c++;
      }
      return c;
    };
    rows.push("", `## ${code(d + "/")}`, "", "| Module | Files | Header comment |", "|---|---|---|");
    for (const s of subdirs) {
      const idx = ["index.ts", "index.tsx"].map((n) => `${d}/${s}/${n}`).find(exists) ?? readdirSync(path.join(ROOT, d, s)).filter((n) => /\.(ts|tsx|js)$/.test(n)).sort().map((n) => `${d}/${s}/${n}`)[0];
      rows.push(`| ${code(s + "/")} | ${count(d + "/" + s)} | ${cell(idx ? headComment(idx) : "")} |`);
    }
    for (const f of topFiles) rows.push(`| ${code(f)} | 1 | ${cell(headComment(`${d}/${f}`))} |`);
  }
  return [gen("Module map", "Directory listing of the Cyrus code with each module's own header comment (the first comment lines of its index or first file)."), ...rows, ""].join("\n");
}

function scriptsPage(): string {
  const rows: string[] = [];
  const push = (rel: string) => rows.push(`| ${code(rel)} | ${cell(headComment(rel))} |`);
  const dirs = ["scripts/cyrus", "scripts/cyrus/data-split", "scripts/platform", "tools/cyrus-api", "tools/nxm"];
  for (const d of dirs) if (exists(d)) for (const n of readdirSync(path.join(ROOT, d)).sort()) { const rel = d + "/" + n; if (statSync(path.join(ROOT, rel)).isFile() && /\.(ts|mjs|js|sh)$/.test(n)) push(rel); }
  for (const rel of ["scripts/ship", "scripts/promote-cyrus.sh"]) if (exists(rel)) push(rel);
  return [gen("Scripts", "Files under scripts/cyrus, scripts/cyrus/data-split, scripts/platform, tools/cyrus-api plus scripts/ship and scripts/promote-cyrus.sh, with their header comments."), "| Script | What it says it does |", "|---|---|", ...rows, ""].join("\n");
}

// ---------- tests ----------
export type TestRow = { file: string; cases: number; real: boolean; head: string };
export function collectTests(): TestRow[] {
  const dir = path.join(ROOT, "test");
  const rows: TestRow[] = [];
  for (const n of readdirSync(dir).sort()) {
    if (!/(cyrus|modbuilder|mod-builder|nxeon-platform)/i.test(n) || !/\.ts$/.test(n)) continue;
    const text = rd("test/" + n);
    const cases = (text.match(/^\s*(?:it|test)(?:\.\w+)?\(/gm) ?? []).length;
    const real = !/\.test\.ts$/.test(n);
    rows.push({ file: "test/" + n, cases, real, head: headComment("test/" + n) });
  }
  return rows;
}

function testsPage(): string {
  const rows = collectTests();
  const unit = rows.filter((r) => !r.real);
  const real = rows.filter((r) => r.real);
  const total = unit.reduce((a, r) => a + r.cases, 0);
  return [
    gen("Test inventory", "Static count of it()/test() calls per file (a lower bound: loops that generate cases count once). The authoritative number is the runner's output; run the suite with `scripts/devhost test`."),
    `${unit.length} unit/integration files with about ${total} static cases, plus ${real.length} "real" harness files (flights against real servers, not run by \`npm test\`). The test only checks that this FILE LIST is current; counts may drift between regenerations.`,
    "",
    "## Suites (run by npm test)", "", "| File | Static cases | Header comment |", "|---|---|---|",
    ...unit.map((r) => `| ${code(r.file)} | ${r.cases} | ${cell(r.head)} |`),
    "",
    "## Real flight and fixture harnesses (not in npm test)", "", "| File | Header comment |", "|---|---|",
    ...real.map((r) => `| ${code(r.file)} | ${cell(r.head)} |`),
    "",
  ].join("\n");
}

// ---------- assembly ----------
function gen(title: string, source: string): string {
  return [`# ${title}`, "", `> GENERATED by \`scripts/cyrus/docs-build.ts\`. Do not edit by hand: change the code (or \`docs/cyrus/_data/features.json\`) and re-run \`npx tsx scripts/cyrus/docs-build.ts\`. ${source}`, ""].join("\n");
}

export async function buildAll(): Promise<Record<string, string>> {
  return {
    [`${REF_DIR}/flags-and-env.md`]: flagsPage(),
    [`${REF_DIR}/routes.md`]: routesPage(),
    [`${REF_DIR}/db-tables.md`]: tablesPage(),
    [`${REF_DIR}/versions.md`]: versionsPage(),
    [`${REF_DIR}/adapters.md`]: await adaptersPage(),
    [`${REF_DIR}/openapi.md`]: openapiPage(),
    [`${REF_DIR}/feature-map.md`]: featurePage(),
    [`${REF_DIR}/modules.md`]: modulesPage(),
    [`${REF_DIR}/scripts.md`]: scriptsPage(),
    [`${REF_DIR}/tests.md`]: testsPage(),
  };
}

async function main() {
  const check = process.argv.includes("--check");
  const pages = await buildAll();
  let stale = 0;
  for (const [rel, content] of Object.entries(pages)) {
    const abs = path.join(ROOT, rel);
    const cur = existsSync(abs) ? readFileSync(abs, "utf8") : null;
    if (cur === content) continue;
    if (check) { stale++; console.error(`STALE ${rel}`); continue; }
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, content);
    console.log(`wrote ${rel}`);
  }
  if (check) {
    if (stale) { console.error(`${stale} generated page(s) stale: run npx tsx scripts/cyrus/docs-build.ts`); process.exit(1); }
    console.log("docs/cyrus/reference is current");
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

