  it("the staff-only admin viewer exists and requires the platform area", () => {
    const p = "app/admin/docs/cyrus/page.tsx";
    assert.ok(existsSync(path.join(ROOT, p)), p + " missing");
    assert.match(rd(p), /requireArea\("platform"\)/);
